    const u = new URL(String(req.query.u || ''));
    if (u.protocol !== 'https:' || !/(^|\.)googlevideo\.com$/i.test(u.hostname)) return res.status(400).end();
    const cl = YT_CLIENTS.find(c => c.n === req.query.c) || YT_CLIENTS[0];
